@dataclass
class NumberNode:
    value: float


@dataclass
class StringNode:
    value: str


@dataclass
class BoolNode:
    value: bool


@dataclass
class IdentNode:
    name: str


@dataclass
class BinOpNode:
    op: str
    left: object
    right: object


@dataclass
class UnaryOpNode:
    op: str
    operand: object


@dataclass
class CallNode:
    name: str
    args: list


@dataclass
class IfNode:
    cond: object
    then_expr: object
    else_expr: object


class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> object:
        if not self.tokens:
            raise ParseError("empty or comment-only source", 0)

        expr = self.expr()
        if self.pos < len(self.tokens):
            raise ParseError("trailing input after expression", self.tokens[self.pos].position)
        return expr

    def expr(self) -> object:
        return self.or_expr()

    def or_expr(self) -> object:
        left = self.and_expr()
        while self._match("KEYWORD", "or"):
            right = self.and_expr()
            left = BinOpNode("or", left, right)
        return left

    def and_expr(self) -> object:
        left = self.not_expr()
        while self._match("KEYWORD", "and"):
            right = self.not_expr()
            left = BinOpNode("and", left, right)
        return left

    def not_expr(self) -> object:
        if self._match("KEYWORD", "not"):
            operand = self.not_expr()
            return UnaryOpNode("not", operand)
        return self.comparison()

    def comparison(self) -> object:
        left = self.additive()

        if self._peek() and self._peek().kind == "OP" and self._peek().value in ("==", "!=", "<", "<=", ">", ">="):
            op = self._advance().value
            right = self.additive()
            return BinOpNode(op, left, right)

        return left

    def additive(self) -> object:
        left = self.multiplicative()
        while self._peek() and self._peek().kind == "OP" and self._peek().value in ("+", "-"):
            op = self._advance().value
            right = self.multiplicative()
            left = BinOpNode(op, left, right)
        return left

    def multiplicative(self) -> object:
        left = self.unary()
        while self._peek() and self._peek().kind == "OP" and self._peek().value in ("*", "/", "%"):
            op = self._advance().value
            right = self.unary()
            left = BinOpNode(op, left, right)
        return left

    def unary(self) -> object:
        if self._peek() and self._peek().kind == "OP" and self._peek().value == "-":
            self._advance()
            operand = self.unary()
            return UnaryOpNode("-", operand)
        return self.power()

    def power(self) -> object:
        left = self.primary()
        if self._peek() and self._peek().kind == "OP" and self._peek().value == "^":
            self._advance()
            right = self.unary()
            return BinOpNode("^", left, right)
        return left

    def primary(self) -> object:
        token = self._peek()
        if not token:
            raise ParseError("unexpected end of input", len(self.tokens) > 0 and self.tokens[-1].position or 0)

        if token.kind == "NUMBER":
            self._advance()
            return NumberNode(token.value)

        if token.kind == "STRING":
            self._advance()
            return StringNode(token.value)

        if token.kind == "KEYWORD":
            self._advance()
            return BoolNode(token.value)

        if token.kind == "IDENT":
            name = token.value
            ident_pos = self.pos
            self._advance()

            if self._peek() and self._peek().kind == "OP" and self._peek().value == "(":
                self._advance()
                args = []
                if self._peek() and not (self._peek().kind == "OP" and self._peek().value == ")"):
                    args.append(self.expr())
                    while self._match("OP", ","):
                        args.append(self.expr())

                if not self._match("OP", ")"):
                    raise ParseError("expected ')'", self._peek().position if self._peek() else len(self.tokens))

                return CallNode(name, args)

            return IdentNode(name)

        if token.kind == "OP" and token.value == "(":
            self._advance()
            expr_result = self.expr()
            if not self._match("OP", ")"):
                raise ParseError("expected ')'", self._peek().position if self._peek() else len(self.tokens))
            return expr_result

        raise ParseError(f"unexpected token: {token.value}", token.position)

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _advance(self):
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def _match(self, kind: str, value: object = None) -> bool:
        token = self._peek()
        if token and token.kind == kind and (value is None or token.value == value):
            self._advance()
            return True
        return False


def parse(source: str) -> object:
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

from .errors import EvalError


def builtin_abs(x: float) -> float:
    """Return absolute value of x."""
    return abs(x)


def builtin_min(*args: float) -> float:
    """Return minimum of arguments."""
    if not args:
        raise EvalError("min() takes 1 argument(s) or more, got 0")
    return min(args)


def builtin_max(*args: float) -> float:
    """Return maximum of arguments."""
    if not args:
        raise EvalError("max() takes 1 argument(s) or more, got 0")
    return max(args)


def builtin_round(x: float, n: float | None = None) -> float:
    """Round x to n decimal places (default 0)."""
    if n is None:
        return float(round(x))
    n_int = int(n)
    if n != n_int:
        raise EvalError("round() n argument must be a whole number")
    return float(round(x, n_int))


def builtin_len(s: str) -> float:
    """Return length of string."""
    return float(len(s))


def builtin_upper(s: str) -> str:
    """Return uppercase version of string."""
    return s.upper()


def builtin_lower(s: str) -> str:
    """Return lowercase version of string."""
    return s.lower()


def builtin_str(value: object) -> str:
    """Convert value to string."""
    if isinstance(value, bool):
        return "true" if value else "false"
    elif isinstance(value, float):
        if value == int(value):
            return str(int(value))
        return repr(value)
    else:
        return value


def builtin_num(s: str) -> float:
    """Convert string to number."""
    try:
        s_stripped = s.strip()
        return float(s_stripped)
    except ValueError:
        raise EvalError(f"cannot parse '{s}' as a number")


BUILTINS = {
    "abs": builtin_abs,
    "min": builtin_min,
    "max": builtin_max,
    "round": builtin_round,
    "len": builtin_len,
    "upper": builtin_upper,
    "lower": builtin_lower,
    "str": builtin_str,
    "num": builtin_num,
}

from .parser import parse, NumberNode, StringNode, BoolNode, IdentNode, BinOpNode, UnaryOpNode, CallNode, IfNode
from .errors import EvalError
from .builtins import BUILTINS


def evaluate(source: str, env: dict | None = None) -> object:
    """Evaluate a minilang expression."""
    if env is None:
        env = {}
    env = dict(env)

    ast = parse(source)
    return _eval(ast, env)


def _eval(node: object, env: dict) -> object:
    """Recursively evaluate an AST node."""
    if isinstance(node, NumberNode):
        return node.value

    if isinstance(node, StringNode):
        return node.value

    if isinstance(node, BoolNode):
        return node.value

    if isinstance(node, IdentNode):
        name = node.name
        if name not in env:
            raise EvalError(f"undefined variable: {name}")
        value = env[name]
        if not isinstance(value, (float, str, bool)):
            raise EvalError(f"unsupported value for {name}: {value!r}")
        return value

    if isinstance(node, BinOpNode):
        return _eval_binop(node, env)

    if isinstance(node, UnaryOpNode):
        return _eval_unary(node, env)

    if isinstance(node, CallNode):
        return _eval_call(node, env)

    if isinstance(node, IfNode):
        return _eval_if(node, env)

    raise EvalError(f"unknown node type: {type(node)}")


def _eval_binop(node: BinOpNode, env: dict) -> object:
    """Evaluate a binary operation."""
    op = node.op

    if op == "or":
        left = _eval(node.left, env)
        if not isinstance(left, bool):
            raise EvalError("'or' requires boolean operands")
        if left:
            return True
        right = _eval(node.right, env)
        if not isinstance(right, bool):
            raise EvalError("'or' requires boolean operands")
        return right

    if op == "and":
        left = _eval(node.left, env)
        if not isinstance(left, bool):
            raise EvalError("'and' requires boolean operands")
        if not left:
            return False
        right = _eval(node.right, env)
        if not isinstance(right, bool):
            raise EvalError("'and' requires boolean operands")
        return right

    left = _eval(node.left, env)
    right = _eval(node.right, env)

    if op == "+":
        if isinstance(left, (int, float)) and isinstance(right, (int, float)):
            return left + right
        if isinstance(left, str) and isinstance(right, str):
            return left + right
        raise EvalError("'+' requires two numbers or two strings")

    if op == "-":
        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            raise EvalError("'-' requires two numbers")
        return left - right

    if op == "*":
        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            raise EvalError("'*' requires two numbers")
        return left * right

    if op == "/":
        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            raise EvalError("'/' requires two numbers")
        if right == 0:
            raise EvalError("division by zero")
        return left / right

    if op == "%":
        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            raise EvalError("'%' requires two numbers")
        if right == 0:
            raise EvalError("modulo by zero")
        return left % right

    if op == "^":
        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            raise EvalError("'^' requires two numbers")
        result = left ** right
        if not isinstance(result, float) or (result != result):
            raise EvalError(f"invalid result from power operation")
        return result

    if op == "==":
        return left == right

    if op == "!=":
        return left != right

    if op == "<":
        if isinstance(left, (int, float)) and isinstance(right, (int, float)):
            return left < right
        if isinstance(left, str) and isinstance(right, str):
            return left < right
        raise EvalError("'<' requires two numbers or two strings")

    if op == "<=":
        if isinstance(left, (int, float)) and isinstance(right, (int, float)):
            return left <= right
        if isinstance(left, str) and isinstance(right, str):
            return left <= right
        raise EvalError("'<=' requires two numbers or two strings")

    if op == ">":
        if isinstance(left, (int, float)) and isinstance(right, (int, float)):
            return left > right
        if isinstance(left, str) and isinstance(right, str):
            return left > right
        raise EvalError("'>' requires two numbers or two strings")

    if op == ">=":
        if isinstance(left, (int, float)) and isinstance(right, (int, float)):
            return left >= right
        if isinstance(left, str) and isinstance(right, str):
            return left >= right
        raise EvalError("'>=' requires two numbers or two strings")

    raise EvalError(f"unknown binary operator: {op}")


def _eval_unary(node: UnaryOpNode, env: dict) -> object:
    """Evaluate a unary operation."""
    op = node.op

    if op == "-":
        operand = _eval(node.operand, env)
        if not isinstance(operand, (int, float)):
            raise EvalError("unary '-' requires a number")
        return -operand

    if op == "not":
        operand = _eval(node.operand, env)
        if not isinstance(operand, bool):
            raise EvalError("'not' requires a boolean")
        return not operand

    raise EvalError(f"unknown unary operator: {op}")


def _eval_call(node: CallNode, env: dict) -> object:
    """Evaluate a function call."""
    name = node.name
    args = [_eval(arg, env) for arg in node.args]

    if name == "if":
        if len(node.args) != 3:
            raise EvalError(f"if() takes 3 argument(s), got {len(node.args)}")
        cond = _eval(node.args[0], env)
        if not isinstance(cond, bool):
            raise EvalError("if() condition must be a boolean")
        if cond:
            return _eval(node.args[1], env)
        else:
            return _eval(node.args[2], env)

    if name not in BUILTINS:
        raise EvalError(f"undefined function: {name}")

    func = BUILTINS[name]
    try:
        if name in ("min", "max"):
            if len(args) == 0:
                raise EvalError(f"{name}() takes 1 argument(s), got 0")
            for arg in args:
                if not isinstance(arg, (int, float)):
                    raise EvalError(f"{name}() arguments must be numbers")
            return func(*args)
        elif name == "round":
            if len(args) not in (1, 2):
                raise EvalError(f"round() takes 1 or 2 argument(s), got {len(args)}")
            if not isinstance(args[0], (int, float)):
                raise EvalError("round() first argument must be a number")
            if len(args) == 2 and not isinstance(args[1], (int, float)):
                raise EvalError("round() second argument must be a number")
            return func(*args)
        elif name == "abs":
            if len(args) != 1:
                raise EvalError(f"abs() takes 1 argument(s), got {len(args)}")
            if not isinstance(args[0], (int, float)):
                raise EvalError("abs() argument must be a number")
            return func(args[0])
        elif name == "len":
            if len(args) != 1:
                raise EvalError(f"len() takes 1 argument(s), got {len(args)}")
            if not isinstance(args[0], str):
                raise EvalError("len() argument must be a string")
            return func(args[0])
        elif name in ("upper", "lower"):
            if len(args) != 1:
                raise EvalError(f"{name}() takes 1 argument(s), got {len(args)}")
            if not isinstance(args[0], str):
                raise EvalError(f"{name}() argument must be a string")
            return func(args[0])
        elif name == "str":
            if len(args) != 1:
                raise EvalError(f"str() takes 1 argument(s), got {len(args)}")
            return func(args[0])
        elif name == "num":
            if len(args) != 1:
                raise EvalError(f"num() takes 1 argument(s), got {len(args)}")
            if not isinstance(args[0], str):
                raise EvalError("num() argument must be a string")
            return func(args[0])
    except EvalError:
        raise

    raise EvalError(f"error calling {name}()")


def _eval_if(node: IfNode, env: dict) -> object:
    """Evaluate if expression."""
    cond = _eval(node.cond, env)
    if not isinstance(cond, bool):
        raise EvalError("if() condition must be a boolean")
    if cond:
        return _eval(node.then_expr, env)
    else:
        return _eval(node.else_expr, env)

import sys
from . import evaluate, MiniLangError


def format_value(value):
    """Format a value for display in the REPL."""
    if isinstance(value, bool):
        return "true" if value else "false"
    elif isinstance(value, float):
        if value == int(value):
            return str(int(value))
        return repr(value)
    elif isinstance(value, str):
        escaped = value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\t", "\\t").replace("\r", "\\r")
        return f'"{escaped}"'
    return str(value)


def main():
    """Run the minilang REPL."""
    env = {}

    try:
        while True:
            try:
                line = input()
            except EOFError:
                break

            if not line or line.isspace():
                continue

            if line == ":quit":
                break

            if line == ":vars":
                for name in sorted(env.keys()):
                    print(f"{name} = {format_value(env[name])}")
                continue

            if "=" in line and not "==" in line:
                parts = line.split("=", 1)
                if len(parts) == 2 and parts[0].isidentifier():
                    name = parts[0].strip()
                    if name.isidentifier():
                        expr_str = parts[1].strip()
                        try:
                            result = evaluate(expr_str, env)
                            env = dict(env)
                            env[name] = result
                            continue
                        except MiniLangError as e:
                            print(f"error: {e}")
                            continue

            try:
                result = evaluate(line, env)
                print(format_value(result))
            except MiniLangError as e:
                print(f"error: {e}")

    sys.exit(0)


if __name__ == "__main__":
    main()

